// @vitest-environment jsdom
/**
 * RELEASE_TEST_CHECKLIST #11 - manual onboarding through the real product seam.
 *
 * PermissionGate, setup surface, Models screen, catalog, model manager, integrity checks,
 * filesystem promotion, installed discovery, and activation remain real. The harness owns only
 * the App shell's `og:navigate` handoff so unrelated app subsystems do not pollute this seam.
 * Electron APIs and HTTP model delivery are the only controlled boundaries.
 */
import { cleanup, render, screen, waitFor, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import React from 'react'
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest'

const originalDataDir = process.env.OFFGRID_DATA_DIR
const testRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'offgrid-manual-setup-'))
const dataDir = path.join(testRoot, 'data')
process.env.OFFGRID_DATA_DIR = dataDir

vi.mock('electron', () => ({
  app: {
    getPath: () => dataDir,
    isPackaged: false,
    getAppPath: () => process.cwd(),
    getVersion: () => 'test'
  },
  safeStorage: {
    isEncryptionAvailable: () => false,
    encryptString: (value: string) => Buffer.from(value),
    decryptString: (value: Buffer) => value.toString()
  }
}))

const manager = await import('@offgrid/core/main/models-manager')
const setup = await import('@offgrid/core/main/setup')
const { CATALOG } = await import('@offgrid/models')

// The chat model is a vision model now (no pure-text kind — every text model
// ships an mmproj). Manual setup just needs two distinct downloadable chat models
// to prove only the CHOSEN one downloads (its files, not the other's).
const chatModels = CATALOG.filter(
  (model) => model.kind === 'vision' && model.files.some((f) => f.name.endsWith('.gguf'))
)
const chosenModel = chatModels[0]
const unchosenModel = chatModels.find((model) => model.id !== chosenModel?.id)
if (!chosenModel || !unchosenModel) {
  throw new Error('Model catalog needs two downloadable chat (vision) models for manual setup')
}

type Progress = import('@offgrid/core/main/models-manager').DownloadProgress

function installStorage(): void {
  const values = new Map<string, string>([['onboarding_completed', 'true']])
  const storage: Storage = {
    get length() {
      return values.size
    },
    clear: () => values.clear(),
    getItem: (key) => values.get(key) ?? null,
    key: (index) => [...values.keys()][index] ?? null,
    removeItem: (key) => values.delete(key),
    setItem: (key, value) => values.set(key, String(value))
  }
  Object.defineProperty(window, 'localStorage', { configurable: true, value: storage })
  vi.stubGlobal('localStorage', storage)
}

function installApi(): { requestedUrls: string[] } {
  const requestedUrls: string[] = []
  const progressListeners = new Set<(progress: Progress) => void>()
  vi.stubGlobal(
    'fetch',
    vi.fn(async (input: string | URL | Request) => {
      const url = String(input)
      requestedUrls.push(url)
      const bytes = Buffer.concat([Buffer.from('GGUF', 'ascii'), Buffer.alloc(2_044, 19)])
      return new Response(new Uint8Array(bytes), {
        status: 200,
        headers: { 'content-length': String(bytes.length) }
      })
    })
  )

  const eventSubscription = (): (() => void) => () => {}
  const values: Record<string, unknown> = {
    isPro: false,
    platform: 'darwin',
    getPermissionStatus: async () => ({
      accessibility: true,
      screenRecording: true,
      allGranted: true
    }),
    checkModelStatus: async () => ({
      downloaded: (await manager.listInstalled()).length > 0,
      modelsDir: path.join(dataDir, 'models')
    }),
    getModelCatalog: manager.getCatalog,
    getInstalledModels: manager.listInstalled,
    getActiveModelIds: manager.getActiveModelIds,
    activateModel: manager.activateModel,
    estimateModelFit: setup.estimateModelFit,
    downloadModel: async (modelId: string) =>
      manager.downloadModel(modelId, (progress) => {
        for (const listener of progressListeners) listener(progress)
      }),
    cancelModelDownload: async (modelId: string) => manager.cancelDownload(modelId),
    onModelProgress: (listener: (progress: Progress) => void) => {
      progressListeners.add(listener)
      return () => progressListeners.delete(listener)
    },
    getLlmSettings: async () => ({ performanceMode: 'balanced' }),
    setLlmSettings: async () => true,
    setupPlan: setup.getSetupPlan,
    systemHealth: async () => ({ ramGb: 64, components: [{ id: 'chat', status: 'ready' }] }),
    imageGenStatus: async () => ({ available: false, models: [], active: '' }),
    getStagedUpdateVersion: async () => null,
    getSettings: async () => ({}),
    listProjects: async () => [],
    getRagConversations: async () => [],
    meetingGetState: async () => ({
      recording: false,
      busy: false,
      platform: null,
      startedAt: 0,
      warnUntil: 0,
      error: ''
    }),
    onNewApproval: eventSubscription,
    onNewAction: eventSubscription,
    onUpdateDownloaded: eventSubscription,
    onReprocessProgress: eventSubscription,
    onSetupProgress: eventSubscription,
    onNavigate: eventSubscription,
    onMeetingState: eventSubscription,
    onRagStream: eventSubscription
  }
  const api = new Proxy(values, {
    get(target, property: string) {
      if (property in target) return target[property]
      return async () => undefined
    }
  })
  Object.assign(window, { api })
  return { requestedUrls }
}

// Electron installs preload before renderer modules evaluate. Preserve that ordering here because
// ModelsScreen intentionally captures the stable preload bridge at module scope.
const apiBoundary = installApi()
const [{ PermissionGate }, { ModelsScreen }] = await Promise.all([
  import('@renderer/components/PermissionGate'),
  import('@renderer/components/ModelsScreen')
])

beforeAll(() => {
  fs.mkdirSync(path.join(dataDir, 'models'), { recursive: true })
})

beforeEach(async () => {
  installStorage()
  window.history.replaceState(null, '', '/models')
  window.matchMedia = vi.fn().mockReturnValue({
    matches: false,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn()
  })
  ;(globalThis as unknown as { ResizeObserver: unknown }).ResizeObserver = class {
    observe(): void {}
    unobserve(): void {}
    disconnect(): void {}
  }
  ;(Element.prototype as unknown as { scrollIntoView: () => void }).scrollIntoView = () => {}
  await manager.clearDownload(chosenModel.id)
  await manager.clearDownload(unchosenModel.id)
  await manager.deleteModel(chosenModel.id)
  await manager.deleteModel(unchosenModel.id)
})

afterEach(() => {
  cleanup()
  vi.unstubAllGlobals()
})

afterAll(async () => {
  await manager.clearDownload(chosenModel.id)
  await manager.clearDownload(unchosenModel.id)
  await manager.deleteModel(chosenModel.id)
  await manager.deleteModel(unchosenModel.id)
  if (originalDataDir === undefined) delete process.env.OFFGRID_DATA_DIR
  else process.env.OFFGRID_DATA_DIR = originalDataDir
  fs.rmSync(testRoot, { recursive: true, force: true })
})

describe('manual model setup', () => {
  it('downloads and activates only the chosen model through manual setup (#11)', async () => {
    const { requestedUrls } = apiBoundary
    function ManualSetupHarness(): React.ReactElement {
      const [view, setView] = React.useState<'workspace' | 'models'>('workspace')
      React.useEffect(() => {
        const navigate = (event: Event): void => {
          if ((event as CustomEvent).detail === 'models') setView('models')
        }
        window.addEventListener('og:navigate', navigate)
        return () => window.removeEventListener('og:navigate', navigate)
      }, [])
      return React.createElement(
        PermissionGate,
        null,
        view === 'models'
          ? React.createElement(ModelsScreen)
          : React.createElement('main', null, 'Application workspace')
      )
    }
    const user = userEvent.setup()
    render(React.createElement(ManualSetupHarness))

    await user.click(await screen.findByRole('button', { name: 'Configure' }))
    await user.click(
      await screen.findByRole('button', { name: 'or browse & pick a model yourself' })
    )
    expect(await screen.findByRole('heading', { name: 'Models' })).not.toBeNull()

    const chosenCard = (await screen.findByText(chosenModel.name)).closest('[role="listitem"]')
    if (!(chosenCard instanceof HTMLElement)) throw new Error('Chosen model card did not render')
    await user.click(within(chosenCard).getByRole('button', { name: 'Download' }))

    let installedCard: HTMLElement | null = null
    await waitFor(() => {
      installedCard = screen.getByText(chosenModel.name).closest('[role="listitem"]')
      if (!(installedCard instanceof HTMLElement)) throw new Error('Installed model card missing')
      expect(within(installedCard).getByRole('button', { name: 'Use' })).not.toBeNull()
    })
    expect(await manager.listInstalled()).toEqual([chosenModel.id])
    expect(requestedUrls).toEqual(chosenModel.files.map((file) => file.url))
    expect(requestedUrls).not.toEqual(expect.arrayContaining(unchosenModel.files.map((f) => f.url)))
    expect(fs.existsSync(path.join(dataDir, 'models', chosenModel.files[0]!.name))).toBe(true)
    expect(fs.existsSync(path.join(dataDir, 'models', unchosenModel.files[0]!.name))).toBe(false)

    if (!(installedCard instanceof HTMLElement)) throw new Error('Installed model card missing')
    await user.click(within(installedCard).getByRole('button', { name: 'Use' }))
    await waitFor(() => expect(manager.getActiveModel()).toBe(chosenModel.id))
    await expect(manager.getActiveModelIds()).resolves.toContain(chosenModel.id)
    await expect(manager.listInstalled()).resolves.not.toContain(unchosenModel.id)
    await waitFor(() => {
      const activeCard = screen.getByText(chosenModel.name).closest('[role="listitem"]')
      if (!(activeCard instanceof HTMLElement)) throw new Error('Active model card missing')
      expect(within(activeCard).getByText('Active')).not.toBeNull()
    })
  })
})

// @vitest-environment jsdom
/**
 * RELEASE_TEST_CHECKLIST #71 - connector setup through the real product seam.
 *
 * The real Integrations screen drives production connector persistence, production MCP discovery,
 * and a real stdio MCP child process. Electron IPC is the native boundary, represented only by a
 * direct bridge to the same functions its handlers invoke. Closing and reopening SQLite proves the
 * connected row and discovered tools survive exactly once.
 */
import { cleanup, render, screen, waitFor, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import fs from 'fs'
import os from 'os'
import path from 'path'
import React from 'react'
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const TMP_DIR = fs.mkdtempSync(path.join(os.tmpdir(), 'offgrid-mcp-setup-'))
const MCP_SERVER = path.resolve(
  process.cwd(),
  'src/main/__tests__/fixtures/mcp-reachable-server.mjs'
)

vi.mock('electron', () => ({
  app: { getPath: () => TMP_DIR, isPackaged: false, getAppPath: () => process.cwd() },
  safeStorage: {
    isEncryptionAvailable: () => false,
    encryptString: (value: string) => Buffer.from(value),
    decryptString: (value: Buffer) => value.toString()
  },
  shell: { openExternal: async () => {} }
}))

beforeEach(async () => {
  const { getDB } = await import('@offgrid/core/main/database')
  const { listConnectors } = await import('@offgrid/core/main/mcp')
  listConnectors()
  getDB().exec('DELETE FROM connectors')
})

afterEach(() => cleanup())

afterAll(async () => {
  const { getDB } = await import('@offgrid/core/main/database')
  try {
    getDB().close()
  } catch {
    // The persistence assertion deliberately closes the first connection.
  }
  fs.rmSync(TMP_DIR, { recursive: true, force: true })
})

describe('<ConnectorsScreen/> connector setup', () => {
  it('persists one reachable connector and reports its discovered connected state (#71)', async () => {
    const connectorRepository = await import('@offgrid/core/main/mcp')
    Object.assign(window, {
      api: {
        mcpList: async () => connectorRepository.listConnectors(),
        mcpAdd: connectorRepository.addConnector,
        mcpTest: connectorRepository.testConnector,
        mcpSetEnabled: connectorRepository.setConnectorEnabled,
        mcpRemove: connectorRepository.removeConnector,
        mcpItems: async () => [],
        mcpIngest: async () => ({ ok: true, count: 0 })
      }
    })

    const { ConnectorsScreen } = await import('@renderer/components/ConnectorsScreen')
    const user = userEvent.setup()
    render(React.createElement(ConnectorsScreen))

    await screen.findByText('Nothing connected yet. Pick one above.')
    await user.click(screen.getByRole('button', { name: /custom/i }))
    await user.click(screen.getByRole('radio', { name: 'stdio (local)' }))
    await user.type(screen.getByPlaceholderText('Name'), 'Reachable synthetic MCP')
    await user.type(screen.getByPlaceholderText('command (e.g. npx)'), process.execPath)
    await user.type(screen.getByPlaceholderText('args'), MCP_SERVER)
    await user.click(screen.getByRole('button', { name: 'Add' }))

    const installedRow = await screen.findByRole('button', { name: /Reachable synthetic MCP/ })
    expect(within(installedRow).getByText('not tested')).not.toBeNull()
    await user.click(installedRow)
    await user.click(await screen.findByRole('button', { name: 'Test' }))

    await waitFor(() => {
      expect(screen.getByText('connected')).not.toBeNull()
      expect(screen.getByText('read_status')).not.toBeNull()
    })
    expect(screen.queryByText('not tested')).toBeNull()

    const { getDB } = await import('@offgrid/core/main/database')
    getDB().close()
    vi.resetModules()

    const reopenedDatabase = await import('@offgrid/core/main/database')
    const reopenedRepository = await import('@offgrid/core/main/mcp')
    const persisted = reopenedRepository.listConnectors()
    expect(persisted).toHaveLength(1)
    expect(persisted[0]).toMatchObject({
      name: 'Reachable synthetic MCP',
      status: 'ok',
      tools: JSON.stringify([
        { name: 'read_status', description: 'Returns the synthetic connector status.' }
      ])
    })
    const count = reopenedDatabase
      .getDB()
      .prepare('SELECT COUNT(*) AS count FROM connectors WHERE name = ?')
      .get('Reachable synthetic MCP') as { count: number }
    expect(count.count).toBe(1)
    reopenedDatabase.getDB().close()
  })
})

import { readFileSync } from 'fs'
import path from 'path'
import { describe, expect, it } from 'vitest'

// buildMcpServer pulls in electron/native modules (llm, imagegen, tts, ...), so
// it can't be exercised in-process. This is a source-level regression guard for
// the SECURITY contract instead: the action tools must be exposed ONLY to an
// authorized request. If someone un-gates them (registers unconditionally, or
// stops threading isActionAuthorized into the build), this test fails.
const SRC = readFileSync(path.join(__dirname, '..', 'mcp-server.ts'), 'utf8')

describe('mcp-server action-tool gate', () => {
  it('registers the action tools only inside the actionsAllowed branch', () => {
    // registerActionTools is *called* exactly once, and it is guarded.
    const calls = SRC.match(/^\s*registerActionTools\(server, authenticatedDeviceId\)/gm) ?? []
    expect(calls.length).toBe(1)
    expect(SRC).toMatch(
      /if \(actionsAllowed\) \{\s*\n\s*registerActionTools\(server, authenticatedDeviceId\)/
    )
  })

  it('builds the per-request server from the request authorization', () => {
    // The only build in the request path is gated on the token check.
    expect(SRC).toMatch(/const authorization = authorizeActionRequest\(req\)/)
    expect(SRC).toMatch(/buildMcpServer\(authorization\.allowed, authorization\.deviceId\)/)
    // buildMcpServer must take the flag — a no-arg call would register nothing
    // OR everything, defeating the gate.
    expect(SRC).toMatch(/buildMcpServer\([\s\S]*actionsAllowed: boolean/)
  })
})

/** Await the usable window, then start cleanup on a later event-loop turn.
 * Cleanup completion must never delay the rest of startup. */
export async function createWindowAndScheduleModelStorageCleanup(
  createWindow: () => Promise<void>,
  cleanup: () => Promise<void>
): Promise<void> {
  await createWindow()
  setImmediate(() => {
    void Promise.resolve()
      .then(cleanup)
      .catch((error) => console.error('[model-storage] Background cleanup failed:', error))
  })
}

import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import Database from 'better-sqlite3-multiple-ciphers'
import { describe, expect, it } from 'vitest'
import { UseEngine } from '@offgrid/use'
import { makeUseDriver } from '../actions/use-driver'
import { buildRegistry } from '../actions/use-runtime'
import { createActionWorker } from '../actions/use-worker'
import { gateHost, onGateParked, whenActionParked, resolveActionGate } from '../actions/gate-host'
import { HOOKS, registerHook, unregisterHook } from '../bootstrap/hookRegistry'
import { NativeActionToolExtension } from '../tools/nativeActionToolExtension'
import type { NativeActionCommand, NativeActionResponse } from '../actions/native-helper-logic'

describe('browser native action approval with the real engine', () => {
  // Browser changes wait for Desktop approval. A web task runs in its owning Chat;
  // without a conversation ID, either origin must use the approval surface.
  it.each([
    ['mail_send', true, 'bridge', 'browser-chat'],
    ['messages_send', true, 'bridge', 'browser-chat'],
    ['calendar_create_event', true, 'bridge', 'browser-chat'],
    ['reminders_create', true, 'bridge', 'browser-chat'],
    ['open_url', false, 'bridge', 'browser-chat'],
    ['web_use', true, 'bridge', undefined],
    ['web_use', true, 'desktop', undefined],
    ['web_use', false, 'bridge', 'browser-chat'],
    ['web_use', false, 'desktop', 'desktop-chat']
  ] as const)('%s waits: %s (%s, %s)', async (name, waits, origin, conversationId) => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'browser-native-approval-'))
    const db = new Database(path.join(root, 'actions.db'))
    const executed: unknown[] = []
    const requests: Array<{ actionId: string }> = []
    const run = async (command: NativeActionCommand): Promise<NativeActionResponse> => {
      executed.push(command)
      return { ok: false, error: 'No native operation was expected' }
    }
    const engine = new UseEngine({
      driver: makeUseDriver(db),
      registry: buildRegistry(run),
      device: {
        execute: async (action) => {
          executed.push(action)
          return { ok: false, detail: 'No device action was expected' }
        }
      },
      gate: gateHost
    })
    const worker = createActionWorker(engine, { onParked: onGateParked })
    // The approval UI accepts the request and waits for the user's decision.
    registerHook(HOOKS.actionsProposeApproval, (request: { actionId: string }) => {
      requests.push(request)
      return true
    })
    try {
      await engine.init()
      const extension = new NativeActionToolExtension(
        {
          run,
          taskUseEnabled: () => true,
          actions: {
            propose: (input, meta) => engine.propose(input, meta),
            waitForOutcome: (id, timeout) => worker.waitForOutcome(id, timeout),
            whenParked: whenActionParked,
            kick: () => worker.kick()
          }
        },
        'darwin'
      )
      const result = await extension.execute(
        name,
        {
          to: 'test@example.test',
          text: 'Synthetic message',
          body: 'Synthetic message',
          title: 'Synthetic event',
          start: '2026-10-12T12:00:00Z',
          url: 'https://example.test',
          goal: 'Read the page'
        },
        { origin, acting: true, conversationId }
      )
      const text = typeof result === 'string' ? result : result.text
      if (waits) {
        // Task tools return on acceptance; the real gate determines whether they can run.
        if (name !== 'web_use') {
          expect(text).toMatch(/waiting for the user's approval in Off Grid AI Desktop/i)
        }
        await expect.poll(() => requests.length).toBe(1)
        expect(executed).toEqual([])
      } else {
        expect(text).not.toMatch(/waiting for the user's approval/i)
        await expect.poll(() => executed.length).toBeGreaterThan(0)
        expect(requests).toEqual([])
      }
    } finally {
      for (const request of requests) {
        const finished = worker.waitForOutcome(request.actionId, 2_000)
        resolveActionGate(request.actionId, { kind: 'reject', reason: 'Test user declined' })
        expect((await finished)?.outcome).toBe('rejected')
      }
      await expect.poll(() => worker.draining()).toBe(false)
      unregisterHook(HOOKS.actionsProposeApproval)
      db.close()
      fs.rmSync(root, { recursive: true, force: true })
    }
    // A declined action never runs; a Chat-owned task and link run without asking.
    if (waits) expect(executed).toEqual([])
    else expect(executed).not.toEqual([])
  })
})

import { describe, expect, it } from 'vitest'
import { OAuthPkceVerifier } from '../mcp-oauth-pkce'

describe('OAuth PKCE verifier lifecycle', () => {
  it('keeps the verifier when the SDK invalidates all credentials before an exchange retry', () => {
    const verifier = new OAuthPkceVerifier()
    verifier.save('attempt-verifier')

    verifier.invalidate('all')

    expect(verifier.read()).toBe('attempt-verifier')
  })

  it('clears the verifier after tokens are saved', () => {
    const verifier = new OAuthPkceVerifier()
    verifier.save('attempt-verifier')

    verifier.complete()

    expect(() => verifier.read()).toThrow('missing PKCE code verifier')
  })

  it('clears the verifier when authorization is cancelled', () => {
    const verifier = new OAuthPkceVerifier()
    verifier.save('attempt-verifier')

    verifier.cancel()

    expect(() => verifier.read()).toThrow('missing PKCE code verifier')
  })

  it('honors explicit verifier invalidation during an active attempt', () => {
    const verifier = new OAuthPkceVerifier()
    verifier.save('attempt-verifier')

    verifier.invalidate('verifier')

    expect(() => verifier.read()).toThrow('missing PKCE code verifier')
  })
})

import { describe, expect, it, vi } from 'vitest'
import { beginOAuthAuthorization, cancelOAuthAuthorization } from '../mcp-oauth-cancellation'

describe('connector OAuth cancellation registry', () => {
  it('cancels only the named connector and clears the registration', () => {
    const first = vi.fn()
    const second = vi.fn()
    beginOAuthAuthorization(101, first)
    beginOAuthAuthorization(202, second)

    expect(cancelOAuthAuthorization(101)).toBe(true)
    expect(first).toHaveBeenCalledWith(
      expect.objectContaining({ message: 'Authorization cancelled' })
    )
    expect(second).not.toHaveBeenCalled()
    expect(cancelOAuthAuthorization(101)).toBe(false)

    cancelOAuthAuthorization(202)
  })

  it('cancels an older attempt when a connector starts a new one', () => {
    const older = vi.fn()
    const newer = vi.fn()
    beginOAuthAuthorization(303, older)
    const finishNewer = beginOAuthAuthorization(303, newer)

    expect(older).toHaveBeenCalledWith(
      expect.objectContaining({ message: 'Authorization superseded by a newer request' })
    )
    finishNewer()
    expect(cancelOAuthAuthorization(303)).toBe(false)
    expect(newer).not.toHaveBeenCalled()
  })

  it('does not let an older completion clear a newer attempt', () => {
    const older = vi.fn()
    const newer = vi.fn()
    const finishOlder = beginOAuthAuthorization(404, older)
    beginOAuthAuthorization(404, newer)

    finishOlder()
    expect(cancelOAuthAuthorization(404)).toBe(true)
    expect(newer).toHaveBeenCalledWith(
      expect.objectContaining({ message: 'Authorization cancelled' })
    )
  })
})

import { describe, expect, it } from 'vitest'
import { authorizeBearer, authorizeBearerAny } from '../mcp-auth-logic'

const TOKEN = 'a'.repeat(64)

describe('authorizeBearer', () => {
  it('accepts the exact Bearer token (case-insensitive scheme)', () => {
    expect(authorizeBearer(`Bearer ${TOKEN}`, TOKEN)).toBe(true)
    expect(authorizeBearer(`bearer ${TOKEN}`, TOKEN)).toBe(true)
    expect(authorizeBearer(`  Bearer   ${TOKEN}  `, TOKEN)).toBe(true)
  })

  it('rejects a wrong, missing, or malformed token (fail closed)', () => {
    expect(authorizeBearer(`Bearer ${'b'.repeat(64)}`, TOKEN)).toBe(false) // wrong value
    expect(authorizeBearer(`Bearer ${TOKEN}x`, TOKEN)).toBe(false) // wrong length
    expect(authorizeBearer(undefined, TOKEN)).toBe(false) // no header
    expect(authorizeBearer(TOKEN, TOKEN)).toBe(false) // missing "Bearer " scheme
    expect(authorizeBearer(`Basic ${TOKEN}`, TOKEN)).toBe(false) // wrong scheme
  })

  it('never authorizes against a blank / too-short configured token', () => {
    expect(authorizeBearer('Bearer ', '')).toBe(false)
    expect(authorizeBearer('Bearer short', 'short')).toBe(false)
  })
})

describe('authorizeBearerAny (per-device: match ANY live token)', () => {
  const A = 'a'.repeat(64)
  const B = 'b'.repeat(64)

  it('authorizes a bearer that matches any token in the live set', () => {
    expect(authorizeBearerAny(`Bearer ${A}`, [A, B])).toBe(true)
    expect(authorizeBearerAny(`Bearer ${B}`, [A, B])).toBe(true)
  })

  it('rejects a bearer that matches NONE of the live tokens', () => {
    expect(authorizeBearerAny(`Bearer ${'c'.repeat(64)}`, [A, B])).toBe(false)
  })

  it('fails closed on an empty set - THIS is the un-paired case', () => {
    // When a device is un-paired its token leaves the live set; with nothing left it can never
    // authorize. An empty set is exactly what a Mac with no tools-allowed peers reports.
    expect(authorizeBearerAny(`Bearer ${A}`, [])).toBe(false)
  })

  it('still rejects a missing / malformed bearer even with tokens present', () => {
    expect(authorizeBearerAny(undefined, [A, B])).toBe(false)
    expect(authorizeBearerAny(A, [A, B])).toBe(false) // no "Bearer " scheme
  })
})

import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { OAuthLoopbackServer } from '../mcp-oauth-loopback'

describe('OAuth loopback callback lifecycle', () => {
  let loopback: OAuthLoopbackServer

  beforeEach(async () => {
    loopback = new OAuthLoopbackServer({
      port: 0,
      authorizationTimeoutMs: 5_000,
      renderCompletionPage: (error) => (error ? `failed:${error}` : 'connected')
    })
    await loopback.start()
  })

  afterEach(async () => {
    await loopback.stop()
  })

  it('keeps a pending request alive after missing and wrong states, then accepts its exact state', async () => {
    const code = loopback.awaitCode('expected-state')

    const missing = await fetch(`${loopback.redirectUrl}?code=attacker-code`)
    const wrong = await fetch(`${loopback.redirectUrl}?state=wrong-state&code=attacker-code`)
    const correct = await fetch(`${loopback.redirectUrl}?state=expected-state&code=provider-code`)

    expect(missing.status).toBe(400)
    expect(await missing.text()).toContain('failed:Invalid or expired authorization response')
    expect(wrong.status).toBe(400)
    expect(await wrong.text()).toContain('failed:Invalid or expired authorization response')
    expect(correct.status).toBe(200)
    await expect(code).resolves.toBe('provider-code')
  })

  it('consumes a valid state once and rejects a replayed callback', async () => {
    const code = loopback.awaitCode('one-time-state')

    const first = await fetch(`${loopback.redirectUrl}?state=one-time-state&code=first-code`)
    const replay = await fetch(`${loopback.redirectUrl}?state=one-time-state&code=replayed-code`)

    expect(first.status).toBe(200)
    await expect(code).resolves.toBe('first-code')
    expect(replay.status).toBe(400)
    expect(await replay.text()).toContain('failed:Invalid or expired authorization response')
  })

  it('removes an expired state and does not admit a late callback', async () => {
    const code = loopback.awaitCode('expired-state', 10)

    await expect(code).rejects.toThrow('Authorization timed out')
    const late = await fetch(`${loopback.redirectUrl}?state=expired-state&code=late-code`)

    expect(late.status).toBe(400)
    expect(await late.text()).toContain('failed:Invalid or expired authorization response')
  })

  it('routes concurrent callbacks only to their exact pending requests', async () => {
    const firstCode = loopback.awaitCode('first-state')
    const secondCode = loopback.awaitCode('second-state')

    await fetch(`${loopback.redirectUrl}?state=second-state&code=second-code`)
    await fetch(`${loopback.redirectUrl}?state=first-state&code=first-code`)

    await expect(firstCode).resolves.toBe('first-code')
    await expect(secondCode).resolves.toBe('second-code')
  })

  it('consumes the exact state when the provider returns an error', async () => {
    const code = loopback.awaitCode('denied-state')
    const rejection = expect(code).rejects.toThrow('OAuth error: access_denied')

    const denied = await fetch(`${loopback.redirectUrl}?state=denied-state&error=access_denied`)

    expect(denied.status).toBe(200)
    expect(await denied.text()).toContain('failed:access_denied')
    await rejection
    const replay = await fetch(`${loopback.redirectUrl}?state=denied-state&code=ignored`)
    expect(replay.status).toBe(400)
  })

  it('consumes an exact state when the provider omits both code and error', async () => {
    const code = loopback.awaitCode('malformed-state')
    const rejection = expect(code).rejects.toThrow('No authorization code in redirect')

    const malformed = await fetch(`${loopback.redirectUrl}?state=malformed-state`)

    expect(malformed.status).toBe(400)
    await rejection
    const replay = await fetch(`${loopback.redirectUrl}?state=malformed-state&code=ignored`)
    expect(replay.status).toBe(400)
  })

  it('rejects missing and duplicate registrations without replacing the original request', async () => {
    expect(() => loopback.awaitCode('')).toThrow('OAuth authorization URL is missing state')
    const original = loopback.awaitCode('duplicate-state')
    expect(() => loopback.awaitCode('duplicate-state')).toThrow(
      'OAuth authorization state is already pending'
    )

    await fetch(`${loopback.redirectUrl}?state=duplicate-state&code=original-code`)
    await expect(original).resolves.toBe('original-code')
  })

  it('cancels only the named request and leaves concurrent authorization intact', async () => {
    const cancelled = loopback.awaitCode('cancelled-state')
    const surviving = loopback.awaitCode('surviving-state')
    const cancellation = expect(cancelled).rejects.toThrow('Authorization superseded')

    loopback.cancel('cancelled-state', new Error('Authorization superseded'))
    loopback.cancel('unknown-state', new Error('Must not affect another request'))
    await fetch(`${loopback.redirectUrl}?state=surviving-state&code=surviving-code`)

    await cancellation
    await expect(surviving).resolves.toBe('surviving-code')
  })

  it('rejects pending requests on shutdown and can start cleanly again', async () => {
    const pending = loopback.awaitCode('shutdown-state')
    const stopped = expect(pending).rejects.toThrow('OAuth callback server stopped')

    await loopback.stop()
    await stopped
    await loopback.start()
    const restarted = loopback.awaitCode('restarted-state')
    await fetch(`${loopback.redirectUrl}?state=restarted-state&code=restarted-code`)

    await expect(restarted).resolves.toBe('restarted-code')
  })

  it('serves the configured logo without changing pending authorization state', async () => {
    await loopback.stop()
    loopback = new OAuthLoopbackServer({
      port: 0,
      renderCompletionPage: (error) => (error ? `failed:${error}` : 'connected'),
      logoBytes: () => Buffer.from('brand-logo')
    })
    await loopback.start()
    const code = loopback.awaitCode('logo-state')

    const logo = await fetch(new URL('/oglogo.png', loopback.redirectUrl))
    await fetch(`${loopback.redirectUrl}?state=logo-state&code=provider-code`)

    expect(logo.status).toBe(200)
    expect(logo.headers.get('content-type')).toBe('image/png')
    expect(await logo.text()).toBe('brand-logo')
    await expect(code).resolves.toBe('provider-code')
  })

  it('rejects pending authorization when the callback port cannot be bound', async () => {
    const occupiedPort = Number(new URL(loopback.redirectUrl).port)
    const observedErrors: Error[] = []
    const blocked = new OAuthLoopbackServer({
      port: occupiedPort,
      renderCompletionPage: () => 'unused',
      onError: (error) => observedErrors.push(error)
    })
    const pending = blocked.awaitCode('blocked-state')
    const callbackFailure = expect(pending).rejects.toThrow('OAuth callback server unavailable')

    await expect(blocked.start()).rejects.toMatchObject({
      code: 'EADDRINUSE',
      message: expect.stringContaining('If another Off Grid AI window is open, close it')
    })

    await callbackFailure
    expect(observedErrors).toHaveLength(1)
    await blocked.stop()
  })

  it('requires the exact callback path', async () => {
    await expect(loopback.start()).resolves.toBeUndefined()
    const code = loopback.awaitCode('path-state')

    const lookalike = await fetch(
      `${loopback.redirectUrl}-lookalike?state=path-state&code=attacker-code`
    )
    const correct = await fetch(`${loopback.redirectUrl}?state=path-state&code=provider-code`)

    expect(lookalike.status).toBe(404)
    const absentLogo = await fetch(new URL('/oglogo.png', loopback.redirectUrl))
    expect(absentLogo.status).toBe(404)
    expect(correct.status).toBe(200)
    await expect(code).resolves.toBe('provider-code')
  })
})

/**
 * Browser APIs that Chromium provides but jsdom does not.
 *
 * This boundary is installed only for DOM test environments. Product components and
 * Radix primitives remain real; the fake owns no timers or subscriptions, and its
 * lifecycle methods are deliberately inert.
 */
import { vi } from 'vitest'
// The DOM globals jsdom lacks. One owner, shared with the db suite - see the file.
import './dom-globals.setup'

// motion/react (framer-motion) drives animations off requestAnimationFrame, which
// jsdom stubs — so an AnimatePresence EXIT animation never completes and the
// dismissed element lingers forever, breaking every "overlay is gone after close"
// assertion (image lightbox, viewer modal). Replace motion with a transparent
// passthrough for the DOM harness: motion.* render as their plain host element
// (animation props stripped) and AnimatePresence renders children directly, so
// entrance is instant and exit unmounts immediately — exactly what the user sees
// once the animation finishes. No test asserts intermediate animation values.
vi.mock('motion/react', async () => {
  const React = await import('react')
  const MOTION_PROPS = new Set([
    'initial',
    'animate',
    'exit',
    'transition',
    'variants',
    'whileHover',
    'whileTap',
    'whileInView',
    'whileFocus',
    'whileDrag',
    'layout',
    'layoutId',
    'drag',
    'onAnimationComplete',
    'onAnimationStart',
    'custom'
  ])
  const strip = (props: Record<string, unknown>): Record<string, unknown> => {
    const out: Record<string, unknown> = {}
    for (const [k, v] of Object.entries(props)) {
      if (!MOTION_PROPS.has(k)) {
        out[k] = v
      }
    }
    return out
  }
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const host = (tag: string): any => {
    const component = React.forwardRef((props: Record<string, unknown>, ref) =>
      React.createElement(tag, { ...strip(props), ref })
    )
    component.displayName = `MotionTest${tag}`
    return component
  }
  // motion.create(Component) wraps a custom component the same way motion.div wraps
  // a host element: render the component itself, animation props stripped.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const create = (Component: any): any => {
    const component = React.forwardRef((props: Record<string, unknown>, ref) =>
      React.createElement(Component, { ...strip(props), ref })
    )
    component.displayName = 'MotionTestCreate'
    return component
  }
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const cache = new Map<string, any>()
  const motion = new Proxy(
    {},
    {
      get: (_t, tag: string) => {
        if (tag === 'create') {
          return create
        }
        if (!cache.has(tag)) {
          cache.set(tag, host(tag))
        }
        return cache.get(tag)
      }
    }
  )
  return {
    motion,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    AnimatePresence: ({ children }: { children: any }) =>
      React.createElement(React.Fragment, null, children),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    MotionConfig: ({ children }: { children: any }) =>
      React.createElement(React.Fragment, null, children),
    useReducedMotion: () => true,
    useAnimate: () => [React.useRef(null), async () => undefined],
    stagger: () => 0
  }
})

/**
 * jsdom implements no scrolling at all, so Element.scrollIntoView is simply absent - calling it
 * throws. Real browsers always have it. Stub it here rather than guarding each call site, so
 * product code is not shaped around a gap in the test environment.
 */
if (typeof Element !== 'undefined' && !Element.prototype.scrollIntoView) {
  Element.prototype.scrollIntoView = function scrollIntoView(): void {}
}

